queries.query:
SELECT 1
  WHERE EXISTS (
    SELECT 1 FROM system_extensions
    WHERE identifier = 'com.crowdstrike.falcon.Agent'
    )
  AND EXISTS (
    SELECT 1 FROM system_extensions
    WHERE state = 'activated_enabled'
    );

SELECT 1
WHERE (
    SELECT COUNT(*)
    FROM launchd
    WHERE path IN (
        '/Library/Apple/System/Library/LaunchDaemons/com.apple.XprotectFramework.PluginService.plist',
        '/Library/Apple/System/Library/LaunchDaemons/com.apple.XProtect.daemon.scan.plist'
    )
) = 2;

SELECT 1 WHERE NOT EXISTS (
  SELECT * FROM plist WHERE
    path = '/var/db/com.apple.xpc.launchd/disabled.plist' AND
    key = 'com.apple.ODSAgent' AND
    value = '0'
);

SELECT 1 WHERE NOT EXISTS (
  SELECT * FROM file_lines WHERE
    path = '/etc/cups/cupsd.conf' AND
    line LIKE '%Allow @LOCAL%'
  );

SELECT 1 WHERE NOT EXISTS (
  SELECT * FROM processes WHERE
    path = '/System/Library/CoreServices/RemoteManagement/ARDAgent.app/Contents/MacOS/ARDAgent'
);

SELECT 1 WHERE NOT EXISTS (
  SELECT * FROM plist WHERE
    path LIKE '/Users/%/Library/Preferences/ByHost/com.apple.Bluetooth.%.plist' AND
    key = 'PrefKeyServicesEnabled' AND
    value = '1'
);

SELECT 1 FROM (SELECT
  COALESCE(JSON_EXTRACT(
      JSON_EXTRACT(json_result, '$.AC Power:'),
      '$.powernap'
  ), '') AS powernap_ac,
  COALESCE(JSON_EXTRACT(
      JSON_EXTRACT(json_result, '$.Battery Power:'),
      '$.powernap'
  ), '') AS powernap_battery
FROM pmset WHERE getting = 'custom' AND powernap_battery != '1' AND powernap_ac != '1');

SELECT 1 FROM (SELECT
  COALESCE(JSON_EXTRACT(
      JSON_EXTRACT(json_result, '$.AC Power:'),
      '$.womp'
  ), '') AS womp_ac,
  COALESCE(JSON_EXTRACT(
      JSON_EXTRACT(json_result, '$.Battery Power:'),
      '$.womp'
  ), '') AS womp_battery
FROM pmset WHERE getting = 'custom' AND womp_battery != '1' AND womp_ac != '1');

SELECT 1 WHERE EXISTS(
  SELECT 1 FROM system_info WHERE
  regex_match(hardware_model, '^Mac[0-9,]+$', 0) != '' OR regex_match(hardware_model, '^MacBook', 0) != 0
)
AND EXISTS(
  SELECT JSON_EXTRACT(system_wide_power_settings, '$.DestroyFVKeyOnStandby') AS destroy_fv_key_on_standby
  FROM (
    SELECT JSON_EXTRACT(json_result, '$.System-wide power settings:') AS system_wide_power_settings FROM pmset
  )
  WHERE destroy_fv_key_on_standby = '1'
)
AND EXISTS(
    SELECT 1 WHERE EXISTS(
      SELECT 1 WHERE EXISTS(
        SELECT 1 FROM system_info WHERE cpu_type = 'x86_64h' OR cpu_type = 'x86_64'
      ) AND EXISTS(
        SELECT
            CAST(JSON_EXTRACT(battery, '$.standbydelaylow') AS INTEGER) AS standbydelaylow,
            CAST(JSON_EXTRACT(battery, '$.standbydelayhigh') AS INTEGER) AS standbydelayhigh,
            CAST(JSON_EXTRACT(battery, '$.highstandbythreshold') AS INTEGER) AS highstandbythreshold,
            CAST(JSON_EXTRACT(battery, '$.hibernatemode') AS INTEGER) AS hibernatemode
        FROM (
            SELECT JSON_EXTRACT(json_result, '$.Battery Power:') as battery FROM pmset WHERE getting = 'custom'
        )
        WHERE standbydelaylow <= 900 AND standbydelayhigh <= 900 AND highstandbythreshold >= 90 AND hibernatemode = 25
      )
    ) OR EXISTS(
      SELECT 1 WHERE EXISTS(
        SELECT 1 FROM system_info WHERE cpu_type = 'arm64e'
      ) AND EXISTS (
        SELECT
            CAST(JSON_EXTRACT(battery, '$.standby') AS INTEGER) AS standby
        FROM (
            SELECT JSON_EXTRACT(json_result, '$.Battery Power:') AS battery FROM pmset WHERE getting = 'custom'
        )
        WHERE standby <= 900
      )
    )
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM corestorage_logical_volume_families WHERE EncryptionType != "AES-XTS"
);

SELECT 1 WHERE EXISTS(
  SELECT * FROM file WHERE path = '/etc/sudoers.d' AND uid = 0 AND gid = 0
) AND EXISTS(
  SELECT
    COALESCE(JSON_EXTRACT(
      json_result, '$.Authentication timestamp timeout'
    ), '') AS authentication_timestamp_timeout
  FROM sudo_info WHERE authentication_timestamp_timeout = '0.0 minutes'
);

SELECT 1 WHERE EXISTS(
  SELECT
    COALESCE(JSON_EXTRACT(
      json_result, '$.Type of authentication timestamp record'
    ), '') AS type_of_auth_timestamp_record
  FROM sudo_info WHERE type_of_auth_timestamp_record = 'tty'
);

SELECT 1 WHERE EXISTS (
  SELECT JSON_EXTRACT(json_result, '$.rule') AS rule
  FROM authdb
  WHERE right_name = 'system.login.screensaver' AND 
  rule LIKE '%authenticate-session-owner%'
);

SELECT 1 WHERE NOT EXISTS (
  SELECT * FROM plist WHERE
    path = '/var/db/com.apple.xpc.launchd/disabled.plist' AND
    key = 'com.openssh.sshd' AND
    value = '0'
)
AND NOT EXISTS (
  SELECT * FROM launchd WHERE
    name = 'com.openssh.sshd'
);

SELECT 1 WHERE EXISTS(
  SELECT 1 FROM system_info WHERE
  regex_match(hardware_model, '^Mac[0-9,]+$', 0) != '' OR regex_match(hardware_model, '^MacBook', 0) != 0
)
AND EXISTS(
  SELECT JSON_EXTRACT(system_wide_power_settings, '$.DestroyFVKeyOnStandby') AS destroy_fv_key_on_standby
  FROM (
    SELECT JSON_EXTRACT(json_result, '$.System-wide power settings:') AS system_wide_power_settings FROM pmset
  )
  WHERE destroy_fv_key_on_standby = '1'
)
AND EXISTS(
    SELECT 1 WHERE EXISTS(
      SELECT 1 WHERE EXISTS(
        SELECT 1 FROM system_info WHERE cpu_type = 'x86_64h' OR cpu_type = 'x86_64'
      ) AND EXISTS(
        SELECT
            CAST(JSON_EXTRACT(battery, '$.standbydelaylow') AS INTEGER) AS standbydelaylow,
            CAST(JSON_EXTRACT(battery, '$.standbydelayhigh') AS INTEGER) AS standbydelayhigh,
            CAST(JSON_EXTRACT(battery, '$.highstandbythreshold') AS INTEGER) AS highstandbythreshold,
            CAST(JSON_EXTRACT(battery, '$.hibernatemode') AS INTEGER) AS hibernatemode
        FROM (
            SELECT JSON_EXTRACT(json_result, '$.Battery Power:') as battery FROM pmset WHERE getting = 'custom'
        )
        WHERE standbydelaylow <= 900 AND standbydelayhigh <= 900 AND highstandbythreshold >= 90 AND hibernatemode = 25
      )
    ) OR EXISTS(
      SELECT 1 WHERE EXISTS(
        SELECT 1 FROM system_info WHERE cpu_type LIKE 'arm64%'
      ) AND EXISTS (
        SELECT
            CAST(JSON_EXTRACT(battery, '$.standby') AS INTEGER) AS standby
        FROM (
            SELECT JSON_EXTRACT(json_result, '$.Battery Power:') AS battery FROM pmset WHERE getting = 'custom'
        )
        WHERE standby <= 900
      )
    )
);

SELECT 1 WHERE NOT EXISTS (
  SELECT * FROM plist WHERE
    path = '/var/db/com.apple.xpc.launchd/disabled.plist' AND
    key = 'com.openssh.sshd' AND
    value = '0'
)
AND NOT EXISTS (
  SELECT 1 FROM processes WHERE path = '/usr/sbin/sshd'
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM managed_policies WHERE
    domain='com.apple.applicationaccess' AND
    name='enforcedSoftwareUpdateDelay' AND
    CAST(value AS INTEGER) > 30
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM listening_ports WHERE port = 5900 AND protocol = 6
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM listening_ports
  WHERE port = 631
    AND address NOT IN ('127.0.0.1', '::1', '')
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM processes WHERE name = 'ARDAgent'
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM sharing_preferences WHERE internet_sharing = 1
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM sharing_preferences WHERE bluetooth_sharing = 1
);

SELECT 1 FROM file
WHERE path = '/private/etc/ntp.conf'
  AND size > 0;

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM plist
  WHERE path = '/Library/Preferences/com.apple.TimeMachine.plist'
    AND key = 'AutoBackup'
    AND value = '0'
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM plist WHERE
    path = '/Library/Preferences/SystemConfiguration/com.apple.smb.server.plist' AND
    key = 'AllowGuestAccess' AND
    value = 1
);

SELECT 1 WHERE NOT EXISTS (
  SELECT 1 FROM file WHERE
    path LIKE '/Users/%'
    AND path != '/Users/Shared/'
    AND mode NOT IN ('0700', '0701', '0710', '0711')
);

SELECT 1 WHERE NOT EXISTS (
  SELECT apps.path FROM apps
  LEFT JOIN file ON file.path = apps.path
  WHERE apps.path LIKE '/Applications/%'
    AND CAST(SUBSTRING(file.mode, -1) AS INTEGER) & 2 != 0
);

SELECT 1 FROM (
  SELECT CAST(JSON_EXTRACT(policy_parameters, '$.minimumLength') AS INTEGER) AS minlength
  FROM password_policy
  WHERE policy_identifier LIKE '%minChars'
  AND minlength >= 15
);

SELECT 1 WHERE
  EXISTS (SELECT 1 FROM pwd_policy WHERE expires_every_n_days > 0 AND expires_every_n_days <= 365)
  OR EXISTS (SELECT 1 FROM pwd_policy WHERE days_to_expiration > 0 AND days_to_expiration <= 365);

SELECT 1 WHERE EXISTS (
  SELECT COALESCE(JSON_EXTRACT(json_result, '$.Type of authentication timestamp record'), '') AS ttype
  FROM sudo_info
  WHERE ttype = 'tty'
);

SELECT 1 WHERE (
  SELECT COUNT(DISTINCT name) FROM processes
  WHERE name IN ('xprotectd', 'XProtectPluginService') AND uid = 0
) = 2;

SELECT 1 WHERE EXISTS (
  SELECT 1 FROM sudo_info
  WHERE json_type(json_result, '$.Log when a command is allowed by sudoers') IS NOT NULL
);

SELECT 1 FROM registry WHERE
  path = 'HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters\MaximumPasswordAge'
AND data <= 30 AND data != 0;

SELECT 1 FROM mdm_bridge where mdm_command_input =
"<SyncBody><Get><CmdID>1</CmdID><Item><Target><LocURI>./Device/Vendor/MSFT/Policy/Result/Audit/AccountLogon_AuditCredentialValidation</LocURI></Target></Item></Get></SyncBody>" 
AND mdm_command_output = "3";

SELECT 1 FROM mdm_bridge where mdm_command_input =
"<SyncBody><Get><CmdID>1</CmdID><Item><Target><LocURI>./Device/Vendor/MSFT/Policy/Result/Audit/AccountManagement_AuditSecurityGroupManagement</LocURI></Target></Item></Get></SyncBody>" 
AND (mdm_command_output = "1" OR mdm_command_output = "3");

-- The registry key is not present when policy is disabled, so query below is returning 1 when policy is disabled and registry value does not exist. It also return 1 in case policy is enabled and its registry value is 1
SELECT 1 WHERE (
  NOT EXISTS ( SELECT 1 FROM registry WHERE key = 'HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System' AND name = 'DisableBkGndGroupPolicy' )
) OR (
  NOT EXISTS ( SELECT 1 FROM registry WHERE path = 'HKEY_LOCAL_MACHINE\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\\DisableBkGndGroupPolicy' AND data = 1 )
);

-- The registry key is not present when policy is disabled, so query below is returning 1 when policy is disabled and registry value does not exist. It also return 1 in case policy is enabled and its registry value is 1 or 2
SELECT 1 WHERE (
  NOT EXISTS ( SELECT 1 FROM registry WHERE key = 'HKEY_LOCAL_MACHINE\\SOFTWARE\\Policies\\Microsoft\\Windows Defender\\Spynet' COLLATE NOCASE AND name = 'SpynetReporting' )
) OR (
  NOT EXISTS ( SELECT 1 FROM registry WHERE path = 'HKEY_LOCAL_MACHINE\\SOFTWARE\\Policies\\Microsoft\\Windows Defender\\Spynet\\SpynetReporting' COLLATE NOCASE AND data != 0 )
);

